@use_kernel_forward_from_hub("RMSNorm")
class TimestralRMSNorm(nn.Module):
    def __init__(self, hidden_size, eps: float = 1e-6) -> None:
        """
        TimestralRMSNorm is equivalent to T5LayerNorm
        """
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)

    def extra_repr(self):
        return f"{tuple(self.weight.shape)}, eps={self.variance_epsilon}"


class TimestralResidualBlock(nn.Module):
    """`output_layer(silu(input_layer(x))) + residual_layer(x)`, used by the patch embedding and the head."""

    def __init__(self, input_dims: int, hidden_dims: int, output_dims: int, use_bias: bool):
        super().__init__()
        self.input_layer = nn.Linear(input_dims, hidden_dims, bias=use_bias)
        self.activation = nn.SiLU()
        self.output_layer = nn.Linear(hidden_dims, output_dims, bias=use_bias)
        self.residual_layer = nn.Linear(input_dims, output_dims, bias=use_bias)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        output = self.output_layer(self.activation(self.input_layer(hidden_states)))
        return output + self.residual_layer(hidden_states)


class TimestralMLP(nn.Module):
    def __init__(self, config: TimestralConfig):
        super().__init__()
        self.gate_proj = nn.Linear(config.hidden_size, config.intermediate_size, bias=config.mlp_bias)
        self.up_proj = nn.Linear(config.hidden_size, config.intermediate_size, bias=config.mlp_bias)
        self.down_proj = nn.Linear(config.intermediate_size, config.hidden_size, bias=config.mlp_bias)
        self.act_fn = nn.SiLU()

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        return self.down_proj(self.act_fn(self.gate_proj(hidden_states)) * self.up_proj(hidden_states))


class TimestralRotaryEmbedding(nn.Module):
    """
    Rotary position embedding with partial rotation: only the first `partial_rotary_factor * head_dim` dimensions
    of a head rotate. The inverse frequencies are zero-padded past that point, which gives `cos=1` and `sin=0`,
    the identity rotation, on the remaining dimensions.
    """

    def __init__(self, config: TimestralConfig):
        super().__init__()
        self.inv_freq = nn.Buffer(self.compute_inv_freq(config), persistent=False)

    @staticmethod
    def compute_inv_freq(config: TimestralConfig) -> torch.Tensor:
        head_dim = config.hidden_size // config.num_attention_heads
        rope_theta = config.rope_parameters["rope_theta"]
        rotary_dim = int(head_dim * config.rope_parameters.get("partial_rotary_factor", 1.0))
        inv_freq = torch.zeros(head_dim // 2, dtype=torch.float32)
        indices = torch.arange(0, rotary_dim, 2, dtype=torch.float32)
        inv_freq[: rotary_dim // 2] = 1.0 / (rope_theta ** (indices / rotary_dim))
        return inv_freq

    @torch.no_grad()
    def forward(self, hidden_states: torch.Tensor, position_ids: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        inv_freq = self.inv_freq.to(device=hidden_states.device, dtype=torch.float32)
        freqs = position_ids[..., None].to(torch.float32) * inv_freq
        embeddings = torch.cat((freqs, freqs), dim=-1)
        return embeddings.cos().to(hidden_states.dtype), embeddings.sin().to(hidden_states.dtype)


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


@use_kernel_forward_from_hub("rotary_pos_emb")
def apply_rotary_pos_emb(q, k, cos, sin, unsqueeze_dim=1):
    """Applies Rotary Position Embedding to the query and key tensors.

    Args:
        q (`torch.Tensor`): The query tensor.
        k (`torch.Tensor`): The key tensor.
        cos (`torch.Tensor`): The cosine part of the rotary embedding.
        sin (`torch.Tensor`): The sine part of the rotary embedding.
        unsqueeze_dim (`int`, *optional*, defaults to 1):
            The 'unsqueeze_dim' argument specifies the dimension along which to unsqueeze cos[position_ids] and
            sin[position_ids] so that they can be properly broadcasted to the dimensions of q and k. For example, note
            that cos[position_ids] and sin[position_ids] have the shape [batch_size, seq_len, head_dim]. Then, if q and
            k have the shape [batch_size, heads, seq_len, head_dim], then setting unsqueeze_dim=1 makes
            cos[position_ids] and sin[position_ids] broadcastable to the shapes of q and k. Similarly, if q and k have
            the shape [batch_size, seq_len, heads, head_dim], then set unsqueeze_dim=2.
    Returns:
        `tuple(torch.Tensor)` comprising of the query and key tensors rotated using the Rotary Position Embedding.
    """
    cos = cos.unsqueeze(unsqueeze_dim)
    sin = sin.unsqueeze(unsqueeze_dim)
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    return q_embed, k_embed


def eager_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: torch.Tensor | None,
    scaling: float,
    dropout: float = 0.0,
    **kwargs: Unpack[TransformersKwargs],
):
    attn_weights = torch.matmul(query, key.transpose(2, 3)) * scaling
    if attention_mask is not None:
        # Timestral builds boolean masks, `True` meaning "may attend".
        attn_weights = attn_weights.masked_fill(~attention_mask, torch.finfo(attn_weights.dtype).min)

    attn_weights = nn.functional.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query.dtype)
    attn_weights = nn.functional.dropout(attn_weights, p=dropout, training=module.training)
    attn_output = torch.matmul(attn_weights, value)
    attn_output = attn_output.transpose(1, 2).contiguous()

    return attn_output, attn_weights


class TimestralAttention(nn.Module):
    """
    Multi-head attention over the time axis (`is_time=True`, with rotary position embeddings) or over the variate
    axis (no position embedding). With a gate, the attention output is multiplied by `sigmoid(gate_proj(x))` before
    the output projection.
    """

    def __init__(self, config: TimestralConfig, is_time: bool):
        super().__init__()
        self.config = config
        self.is_time = is_time
        self.head_dim = config.hidden_size // config.num_attention_heads
        self.scaling = self.head_dim**-0.5
        self.is_causal = False

        self.q_proj = nn.Linear(config.hidden_size, config.hidden_size, bias=config.attention_bias)
        self.k_proj = nn.Linear(config.hidden_size, config.hidden_size, bias=config.attention_bias)
        self.v_proj = nn.Linear(config.hidden_size, config.hidden_size, bias=config.attention_bias)
        self.o_proj = nn.Linear(config.hidden_size, config.hidden_size, bias=config.attention_bias)
        use_gate = config.time_attention_gate if is_time else config.variate_attention_gate
        self.gate_proj = (
            nn.Linear(config.hidden_size, config.hidden_size, bias=config.attention_bias) if use_gate else None
        )

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        position_embeddings: tuple[torch.Tensor, torch.Tensor] | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor, torch.Tensor | None]:
        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)

        query_states = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        key_states = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        value_states = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)

        if position_embeddings is not None:
            cos, sin = position_embeddings
            query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, eager_attention_forward
        )
        attn_output, attn_weights = attention_interface(
            self,
            query_states,
            key_states,
            value_states,
            attention_mask,
            dropout=0.0,
            scaling=self.scaling,
            is_causal=False,
            **kwargs,
        )

        attn_output = attn_output.reshape(*input_shape, -1).contiguous()
        if self.gate_proj is not None:
            attn_output = attn_output * torch.sigmoid(self.gate_proj(hidden_states))
        attn_output = self.o_proj(attn_output)
        return attn_output, attn_weights


class TimestralLayer(GradientCheckpointingLayer):
    """The attention sublayers of one block type, in order, each a pre-norm residual, followed by one MLP."""

    def __init__(self, config: TimestralConfig, layer_idx: int):
        super().__init__()
        # `"time_variate"` runs an attention over time, then one over variates.
        axes = [axis == "time" for axis in config.block_types[layer_idx].split("_")]
        self.attention_layernorms = nn.ModuleList(
            [TimestralRMSNorm(config.hidden_size, eps=config.rms_norm_eps) for _ in axes]
        )
        self.attentions = nn.ModuleList([TimestralAttention(config, is_time=is_time) for is_time in axes])
        self.mlp_layernorm = TimestralRMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.mlp = TimestralMLP(config)

    def forward(
        self,
        hidden_states: torch.Tensor,
        time_attention_mask: torch.Tensor | None = None,
        variate_attention_mask: torch.Tensor | None = None,
        position_embeddings: tuple[torch.Tensor, torch.Tensor] | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.Tensor:
        batch_size, num_variates, sequence_length, hidden_size = hidden_states.shape
        for layernorm, attention in zip(self.attention_layernorms, self.attentions):
            residual = hidden_states
            hidden_states = layernorm(hidden_states)
            if attention.is_time:
                # One sequence of patches per variate.
                hidden_states = hidden_states.reshape(batch_size * num_variates, sequence_length, hidden_size)
                hidden_states, _ = attention(
                    hidden_states,
                    attention_mask=time_attention_mask,
                    position_embeddings=position_embeddings,
                    **kwargs,
                )
                hidden_states = hidden_states.reshape(batch_size, num_variates, sequence_length, hidden_size)
            else:
                # One sequence of variates per patch.
                hidden_states = hidden_states.transpose(1, 2).reshape(
                    batch_size * sequence_length, num_variates, hidden_size
                )
                hidden_states, _ = attention(hidden_states, attention_mask=variate_attention_mask, **kwargs)
                hidden_states = hidden_states.reshape(
                    batch_size, sequence_length, num_variates, hidden_size
                ).transpose(1, 2)
            hidden_states = residual + hidden_states

        residual = hidden_states
        hidden_states = self.mlp(self.mlp_layernorm(hidden_states))
        return residual + hidden_states


