# Roles a variate (a row of the model input) can take.
TIMESTRAL_ROLE_TARGET = 0
TIMESTRAL_ROLE_KNOWN_COVARIATE = 2


def _causal_statistics(
    values: torch.Tensor, observed_mask: torch.Tensor, minimum_scale: float
) -> tuple[torch.Tensor, torch.Tensor]:
    """
    Causal running mean and standard deviation along the last axis, computed in float64.

    Position `t` only uses the observed values at positions `0..t`. The variance uses Bessel's correction and the
    standard deviation is clamped to `minimum_scale`.
    """
    with torch.no_grad():
        values_64 = values.to(torch.float64)
        weights = observed_mask.to(torch.float64)
        denominator = torch.cumsum(weights, dim=-1).clamp_min(1.0)
        means = torch.cumsum(weights * values_64, dim=-1) / denominator
        previous_means = torch.zeros_like(means)
        previous_means[..., 1:] = means[..., :-1]
        increments = (values_64 - previous_means) * (values_64 - means) * weights
        variance = torch.cumsum(increments, dim=-1) / torch.clamp(denominator - 1.0, min=1.0)
        scales = torch.sqrt(variance).clamp(min=minimum_scale)
    return means.to(values.dtype), scales.to(values.dtype)


def _causal_patch_statistics(
    values: torch.Tensor, observed_mask: torch.Tensor, patch_length: int, minimum_scale: float
) -> tuple[torch.Tensor, torch.Tensor]:
    """
    Per-patch `(loc, scale)`, broadcast back to every time step of the patch. Each patch uses the statistics of
    everything observed up to its last time step.
    """
    means, scales = _causal_statistics(values, observed_mask, minimum_scale)
    loc = means.unfold(-1, patch_length, patch_length)[..., -1]
    scale = scales.unfold(-1, patch_length, patch_length)[..., -1]
    return loc.repeat_interleave(patch_length, dim=-1), scale.repeat_interleave(patch_length, dim=-1)


def _instance_statistics(
    values: torch.Tensor, observed_mask: torch.Tensor, minimum_scale: float
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """
    Non-causal mean and standard deviation of each row over its observed positions, used for known covariates.

    Rows whose observed values are all 0 or 1 (indicators) keep `loc=0` and `scale=1`. Returns
    `(loc, scale, is_binary)`, each of shape `(..., 1)`.
    """
    work_dtype = torch.promote_types(values.dtype, torch.float32)
    values_work = values.to(work_dtype)
    weights = observed_mask.to(work_dtype)
    count = weights.sum(dim=-1, keepdim=True).clamp(min=1.0)
    loc = (values_work * weights).sum(dim=-1, keepdim=True) / count
    variance = (((values_work - loc) * weights) ** 2).sum(dim=-1, keepdim=True) / count
    scale = variance.sqrt().clamp_min(minimum_scale)
    is_zero_one = ((values == 0.0) | (values == 1.0) | ~observed_mask).all(dim=-1, keepdim=True)
    is_binary = is_zero_one & observed_mask.any(dim=-1, keepdim=True)
    loc = torch.where(is_binary, torch.zeros_like(loc), loc)
    scale = torch.where(is_binary, torch.ones_like(scale), scale)
    return loc.to(values.dtype), scale.to(values.dtype), is_binary


def _scale_values(
    values: torch.Tensor, loc: torch.Tensor, scale: torch.Tensor, observed_mask: torch.Tensor, use_asinh: bool
) -> torch.Tensor:
    """`asinh((values - loc) / scale)` on observed positions, 0 elsewhere. Computed in at least float32."""
    output_dtype = torch.promote_types(torch.promote_types(values.dtype, loc.dtype), scale.dtype)
    work_dtype = torch.promote_types(output_dtype, torch.float32)
    scaled = (values.to(work_dtype) - loc.to(work_dtype)) / scale.to(work_dtype).clamp_min(torch.finfo(work_dtype).eps)
    scaled = scaled.masked_fill(~observed_mask, 0.0)
    if use_asinh:
        scaled = torch.where(observed_mask, scaled.asinh(), scaled)
    return scaled.to(output_dtype)


def _encoder_key_validity(observed_patches: torch.Tensor, attend_missing: bool) -> torch.Tensor:
    """
    Which context patches can be attended, of shape `(num_rows, num_patches)`.

    A patch is a valid key if it is observed, or if `attend_missing` is set and its row has started at or before
    it. Leading patches without observations are left padding and are never valid keys.
    """
    if not attend_missing:
        return observed_patches
    started = observed_patches.cummax(dim=-1).values
    return observed_patches | started


def _encoder_causal_mask(key_valid: torch.Tensor) -> torch.Tensor:
    """Causal mask over the valid keys, `(num_rows, num_patches, num_patches)`, with the diagonal always open."""
    num_patches = key_valid.shape[-1]
    causal = torch.tril(torch.ones(num_patches, num_patches, dtype=torch.bool, device=key_valid.device))
    diagonal = torch.eye(num_patches, dtype=torch.bool, device=key_valid.device)
    return (causal[None] & key_valid[:, None, :]) | diagonal[None]


def _context_only_time_mask(key_valid: torch.Tensor, num_prediction_patches: int) -> torch.Tensor:
    """
    Time mask of one block without covariates, `(num_rows, 1, L + h, L + h)` for `L` context patches followed by
    `h` forecast tokens. `True` means "may attend".

    The context is causal. Every forecast token reads the whole valid context and the forecast tokens before it.
    The context never reads the forecast tokens.
    """
    num_rows, num_context_patches = key_valid.shape
    device = key_valid.device
    context_to_context = _encoder_causal_mask(key_valid)
    context_to_forecast = torch.zeros(
        num_rows, num_context_patches, num_prediction_patches, dtype=torch.bool, device=device
    )
    forecast_to_context = key_valid[:, None, :].expand(num_rows, num_prediction_patches, num_context_patches)
    forecast_to_forecast = torch.tril(
        torch.ones(num_prediction_patches, num_prediction_patches, dtype=torch.bool, device=device)
    )[None].expand(num_rows, num_prediction_patches, num_prediction_patches)
    top = torch.cat([context_to_context, context_to_forecast], dim=2)
    bottom = torch.cat([forecast_to_context, forecast_to_forecast], dim=2)
    return torch.cat([top, bottom], dim=1).unsqueeze(1)


def _window_time_mask(
    num_context_patches: int,
    block_size: int,
    key_valid: torch.Tensor,
    bidirectional_rows: torch.Tensor | None,
) -> torch.Tensor:
    """
    Time mask of one block with covariates, `(num_rows, 1, 2N, 2N)`. The sequence holds the `N` patches of the
    whole window (context then horizon) followed by `N` forecast tokens, one per patch. `True` means "may attend".

    - Patch to patch: causal over the valid keys, and unrestricted for `bidirectional_rows` (known covariates).
    - Patch to forecast token: never.
    - Forecast token to patch: a forecast token of the block anchored at `b` reads the valid patches before `b`.
    - Forecast token to forecast token: causal inside a block. Every forecast token reads itself.
    """
    num_rows, num_patches = key_valid.shape
    device = key_valid.device
    positions = torch.arange(num_patches, device=device)[None, :]
    active = positions >= num_context_patches
    offset = (positions - num_context_patches).clamp(min=0)
    anchor = num_context_patches + block_size * (offset // block_size)
    anchor = torch.where(active, anchor, torch.zeros_like(anchor)).expand(num_rows, num_patches)
    active = active.expand(num_rows, num_patches)

    causal = torch.tril(torch.ones(num_patches, num_patches, dtype=torch.bool, device=device))
    diagonal = torch.eye(num_patches, dtype=torch.bool, device=device)
    patch_to_patch = _encoder_causal_mask(key_valid)
    if bidirectional_rows is not None:
        bidirectional = key_valid[:, None, :].expand(num_rows, num_patches, num_patches) | diagonal[None]
        patch_to_patch = torch.where(bidirectional_rows[:, None, None], bidirectional, patch_to_patch)
    patch_to_forecast = torch.zeros(num_rows, num_patches, num_patches, dtype=torch.bool, device=device)
    key_positions = torch.arange(num_patches, device=device).view(1, 1, num_patches)
    forecast_to_patch = active[:, :, None] & (key_positions < anchor[:, :, None]) & key_valid[:, None, :]
    same_block = anchor[:, :, None] == anchor[:, None, :]
    forecast_to_forecast = same_block & causal[None] & active[:, :, None] & active[:, None, :]
    forecast_to_forecast = forecast_to_forecast | diagonal[None]
    top = torch.cat([patch_to_patch, patch_to_forecast], dim=2)
    bottom = torch.cat([forecast_to_patch, forecast_to_forecast], dim=2)
    return torch.cat([top, bottom], dim=1).unsqueeze(1)


def _variate_mask(
    key_valid: torch.Tensor,
    num_forecast_tokens: int,
    target_variates: torch.Tensor | None = None,
    bidirectional_variates: torch.Tensor | None = None,
) -> torch.Tensor | None:
    """
    Variate mask of shape `(batch_size * sequence_length, 1, num_variates, num_variates)`, or `None` when there is
    a single variate. `True` means "may attend".

    A variate reads the other variates of its series. On patch tokens the key must also be valid. On every token:

    - a covariate may not read a target, covariates being exogenous;
    - a known covariate (`bidirectional_variates`) may not read a causal variate, otherwise its view of the
      future could relay the future of a target back into it.

    The diagonal is always open.

    Args:
        key_valid (`torch.Tensor` of shape `(batch_size, num_variates, num_patches)`):
            Which patches can be attended.
        num_forecast_tokens (`int`):
            Number of forecast tokens following the patches.
        target_variates (`torch.Tensor` of shape `(num_variates,)`, *optional*):
            Which variates are targets.
        bidirectional_variates (`torch.Tensor` of shape `(num_variates,)`, *optional*):
            Which variates are known covariates.
    """
    batch_size, num_variates, _ = key_valid.shape
    if num_variates == 1:
        return None
    device = key_valid.device
    forecast_valid = torch.ones(batch_size, num_variates, num_forecast_tokens, dtype=torch.bool, device=device)
    token_valid = torch.cat([key_valid, forecast_valid], dim=-1)
    sequence_length = token_valid.shape[-1]
    mask = token_valid.permute(0, 2, 1)[:, :, None, :].expand(batch_size, sequence_length, num_variates, num_variates)
    if target_variates is not None or bidirectional_variates is not None:
        forbidden = torch.zeros(num_variates, num_variates, dtype=torch.bool, device=device)
        if target_variates is not None:
            forbidden = forbidden | ((~target_variates[:, None]) & target_variates[None, :])
        if bidirectional_variates is not None:
            forbidden = forbidden | (bidirectional_variates[:, None] & (~bidirectional_variates)[None, :])
        mask = mask & ~forbidden
    mask = mask | torch.eye(num_variates, dtype=torch.bool, device=device)
    return mask.reshape(batch_size * sequence_length, 1, num_variates, num_variates)


@auto_docstring
class TimestralModel(TimestralPreTrainedModel):
    def __init__(self, config: TimestralConfig):
        super().__init__(config)

        self.input_ff_layer = TimestralResidualBlock(
            input_dims=2 * config.patch_length,
            hidden_dims=4 * config.hidden_size,
            output_dims=config.hidden_size,
            use_bias=True,
        )
        self.forecast_query = nn.Parameter(torch.zeros(config.hidden_size))
        self.layers = nn.ModuleList(
            [TimestralLayer(config, layer_idx) for layer_idx in range(config.num_hidden_layers)]
        )
        self.norm = TimestralRMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.rotary_emb = TimestralRotaryEmbedding(config)
        self.gradient_checkpointing = False

        # Initialize weights and apply final processing
        self.post_init()

    def _scale_known_covariates(
        self,
        values: torch.Tensor,
        observed_mask: torch.Tensor,
        scaled: torch.Tensor,
        loc: torch.Tensor,
        scale: torch.Tensor,
        known_rows: torch.Tensor,
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        """
        Normalizes the rows of known covariates with the statistics of the whole row, their future being known.
        Indicator rows (values in `{0, 1}`) skip the `asinh`.
        """
        if not bool(known_rows.any()):
            return scaled, loc, scale
        known_loc, known_scale, is_binary = _instance_statistics(values, observed_mask, self.config.minimum_scale)
        known_scaled = _scale_values(values, known_loc, known_scale, observed_mask, use_asinh=False)
        if self.config.use_asinh:
            work_dtype = torch.promote_types(known_scaled.dtype, torch.float32)
            squashed = known_scaled.to(work_dtype).asinh().to(known_scaled.dtype)
            known_scaled = torch.where(observed_mask & ~is_binary, squashed, known_scaled)
        selected = known_rows[:, None]
        return (
            torch.where(selected, known_scaled, scaled),
            torch.where(selected, known_loc, loc),
            torch.where(selected, known_scale, scale),
        )

    @merge_with_config_defaults
    @capture_outputs
    @auto_docstring
    def forward(
        self,
        past_values: torch.Tensor,
        past_observed_mask: torch.Tensor | None = None,
        num_prediction_patches: int | None = None,
        variate_roles: torch.LongTensor | None = None,
        future_known_values: torch.Tensor | None = None,
        future_known_observed_mask: torch.Tensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> TimestralOutput:
        r"""
        past_values (`torch.Tensor` of shape `(batch_size, num_variates, sequence_length)`):
            Context of every variate (targets first, then covariates). `sequence_length` must be a multiple of
            `config.patch_length`. The variates of a series attend each other.
        past_observed_mask (`torch.BoolTensor` of shape `(batch_size, num_variates, sequence_length)`, *optional*):
            Which values of `past_values` are observed. Defaults to all of them.
        num_prediction_patches (`int`, *optional*):
            Number of patches to forecast in this block. Defaults to `config.block_size`.
        variate_roles (`torch.LongTensor` of shape `(num_variates,)`, *optional*):
            Role of each variate: `0` for a target, `1` for a covariate known over the context only and `2` for a
            covariate also known over the horizon. Defaults to targets only.
        future_known_values (`torch.Tensor` of shape `(batch_size, num_variates, num_prediction_patches * patch_length)`, *optional*):
            Values of the known covariates over the block. The rows of the other variates are ignored.
        future_known_observed_mask (`torch.BoolTensor` of shape `(batch_size, num_variates, num_prediction_patches * patch_length)`, *optional*):
            Which values of `future_known_values` are observed.
        """
        config = self.config
        patch_length = config.patch_length
        batch_size, num_variates, sequence_length = past_values.shape
        device = past_values.device
        num_rows = batch_size * num_variates
        if sequence_length % patch_length != 0:
            raise ValueError(
                f"The context length ({sequence_length}) must be a multiple of the patch length ({patch_length})."
            )
        if num_prediction_patches is None:
            num_prediction_patches = config.block_size
        if past_observed_mask is None:
            past_observed_mask = torch.ones_like(past_values, dtype=torch.bool)
        past_observed_mask = past_observed_mask.bool()

        use_covariates = (
            config.use_covariates
            and variate_roles is not None
            and bool((variate_roles != TIMESTRAL_ROLE_TARGET).any())
        )
        if use_covariates:
            if num_prediction_patches > config.block_size:
                raise ValueError(
                    f"With covariates, a block holds at most `config.block_size` ({config.block_size}) patches, "
                    f"got {num_prediction_patches}."
                )
            horizon_length = num_prediction_patches * patch_length
            if future_known_values is None:
                future_known_values = past_values.new_zeros(batch_size, num_variates, horizon_length)
                future_known_observed_mask = torch.zeros_like(future_known_values, dtype=torch.bool)
            if future_known_observed_mask is None:
                raise ValueError("`future_known_observed_mask` is required alongside `future_known_values`.")
            # The window holds the context and the horizon, so that the future of a known covariate is a key.
            # Targets and covariates only known over the context keep a blank horizon.
            values = torch.cat([past_values, future_known_values], dim=-1).reshape(num_rows, -1)
            observed_mask = torch.cat([past_observed_mask, future_known_observed_mask.bool()], dim=-1)
            observed_mask = observed_mask.reshape(num_rows, -1)
        else:
            values = past_values.reshape(num_rows, -1)
            observed_mask = past_observed_mask.reshape(num_rows, -1)
        num_context_patches = sequence_length // patch_length
        num_patches = values.shape[-1] // patch_length

        # Causal normalization of every patch, then patch embedding from the `[values, missing]` channels.
        loc, scale = _causal_patch_statistics(values, observed_mask, patch_length, config.minimum_scale)
        scaled = _scale_values(values, loc, scale, observed_mask, config.use_asinh)
        known_rows = None
        if use_covariates:
            known_rows = (variate_roles == TIMESTRAL_ROLE_KNOWN_COVARIATE).repeat(batch_size)
            scaled, loc, scale = self._scale_known_covariates(values, observed_mask, scaled, loc, scale, known_rows)
        patches = torch.cat(
            [
                scaled.reshape(num_rows, num_patches, patch_length),
                (~observed_mask).reshape(num_rows, num_patches, patch_length).to(scaled.dtype),
            ],
            dim=-1,
        )
        patch_embeddings = self.input_ff_layer(patches.to(self.input_ff_layer.input_layer.weight.dtype))

        # Attention masks and time positions. Positions are anchored at the first patch a series observes.
        observed_patches = observed_mask.unflatten(-1, (num_patches, patch_length)).any(dim=-1)
        key_valid = _encoder_key_validity(observed_patches, config.attend_missing_patches)
        first_observed = observed_patches.reshape(batch_size, num_variates, num_patches).any(dim=1)
        first_observed = first_observed.to(torch.long).argmax(dim=-1).repeat_interleave(num_variates)
        if use_covariates:
            num_forecast_tokens = num_patches
            time_attention_mask = _window_time_mask(num_context_patches, config.block_size, key_valid, known_rows)
            variate_attention_mask = _variate_mask(
                key_valid.reshape(batch_size, num_variates, num_patches),
                num_forecast_tokens,
                target_variates=variate_roles == TIMESTRAL_ROLE_TARGET,
                bidirectional_variates=variate_roles == TIMESTRAL_ROLE_KNOWN_COVARIATE,
            )
            # A patch and its forecast token share a time position.
            position_ids = torch.arange(num_patches, device=device)[None, :] - first_observed[:, None]
            position_ids = torch.cat([position_ids, position_ids], dim=-1)
        else:
            num_forecast_tokens = num_prediction_patches
            time_attention_mask = _context_only_time_mask(key_valid, num_prediction_patches)
            variate_attention_mask = _variate_mask(
                key_valid.reshape(batch_size, num_variates, num_patches), num_forecast_tokens
            )
            position_ids = torch.arange(num_patches + num_prediction_patches, device=device)[None, :]
            position_ids = position_ids - first_observed[:, None]

        forecast_tokens = self.forecast_query.view(1, 1, -1).expand(num_rows, num_forecast_tokens, -1)
        hidden_states = torch.cat([patch_embeddings, forecast_tokens], dim=1)
        position_embeddings = self.rotary_emb(hidden_states, position_ids)

        hidden_states = hidden_states.reshape(batch_size, num_variates, -1, config.hidden_size)
        for layer in self.layers:
            hidden_states = layer(
                hidden_states,
                time_attention_mask=time_attention_mask,
                variate_attention_mask=variate_attention_mask,
                position_embeddings=position_embeddings,
                **kwargs,
            )
        hidden_states = self.norm(hidden_states)

        # The forecast tokens of the block are the last tokens of the sequence. The forecast is expressed in the
        # frame of the last context patch.
        anchor = (num_context_patches - 1) * patch_length
        return TimestralOutput(
            last_hidden_state=hidden_states[:, :, -num_prediction_patches:],
            loc=loc[:, anchor].reshape(batch_size, num_variates),
            scale=scale[:, anchor].reshape(batch_size, num_variates),
        )


TIMESTRAL_ROLE_PAST_COVARIATE = 1


def _clamp_nonfinite(values: torch.Tensor) -> torch.Tensor:
    """
    Maps +/-inf (a `sinh` overflow) to the nearest finite value along the last axis. A position whose whole last
    axis is infinite becomes 0. NaN is left untouched so that real instabilities still surface.
    """
    clamped = torch.where(
        values == float("inf"),
        torch.where(values.isfinite(), values, -float("inf")).amax(dim=-1, keepdim=True),
        torch.where(
            values == -float("inf"),
            torch.where(values.isfinite(), values, float("inf")).amin(dim=-1, keepdim=True),
            values,
        ),
    )
    return torch.where(clamped.isinf(), torch.zeros_like(clamped), clamped)


def _unscale_quantiles(
    predictions: torch.Tensor, loc: torch.Tensor, scale: torch.Tensor, use_asinh: bool
) -> torch.Tensor:
    """Inverse of [`_scale_values`], `sinh(predictions) * scale + loc`, with infinities clamped."""
    output_dtype = torch.promote_types(torch.promote_types(predictions.dtype, loc.dtype), scale.dtype)
    work_dtype = torch.promote_types(output_dtype, torch.float32)
    predictions = predictions.to(work_dtype)
    if use_asinh:
        predictions = predictions.sinh()
    return _clamp_nonfinite((predictions * scale.to(work_dtype) + loc.to(work_dtype)).to(output_dtype))


def _monotone_quantiles(raw: torch.Tensor, quantiles: list[float], width_factor: float) -> torch.Tensor:
    """
    Non-crossing quantiles from raw head outputs along the last axis.

    The median channel is free. The other channels fan out from it as
    `median -/+ cumsum(width_factor * gap * softplus(raw))`, where `gap` is the probability gap to the next level
    towards the median, so that an uneven spacing of the levels is respected.
    """
    median_index = quantiles.index(0.5)
    gaps = [0.0] * len(quantiles)
    for idx in range(median_index + 1, len(quantiles)):
        gaps[idx] = quantiles[idx] - quantiles[idx - 1]
    for idx in range(median_index):
        gaps[idx] = quantiles[idx + 1] - quantiles[idx]
    gaps = torch.tensor(gaps, device=raw.device, dtype=raw.dtype)
    increments = width_factor * gaps * nn.functional.softplus(raw)
    median = raw[..., median_index : median_index + 1]
    upper = torch.cumsum(increments[..., median_index + 1 :], dim=-1)
    lower = torch.flip(torch.cumsum(torch.flip(increments[..., :median_index], dims=[-1]), dim=-1), dims=[-1])
    largest = torch.finfo(raw.dtype).max
    return torch.cat([median - lower, median, median + upper], dim=-1).clamp(min=-largest, max=largest)


def _welford_combine(
    count_a: torch.Tensor,
    mean_a: torch.Tensor,
    m2_a: torch.Tensor,
    count_b: torch.Tensor,
    mean_b: torch.Tensor,
    m2_b: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Merges two Welford states `(count, mean, m2)` element-wise. `(0, 0, 0)` is the identity."""
    count = count_a + count_b
    safe_count = count.clamp(min=torch.finfo(count.dtype).tiny)
    delta = mean_b - mean_a
    mean = mean_a + delta * count_b / safe_count
    m2 = m2_a + m2_b + delta.square() * count_a * count_b / safe_count
    is_empty = count == 0
    mean = torch.where(is_empty, torch.zeros_like(mean), mean)
    m2 = torch.where(is_empty, torch.zeros_like(m2), m2)
    return count, mean, m2


def _cumulative_welford(
    count: torch.Tensor, mean: torch.Tensor, m2: torch.Tensor
) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Inclusive prefix scan of Welford states along dimension 1, in `log2(num_patches)` merges."""
    num_patches = count.shape[1]
    shift = 1
    while shift < num_patches:
        padding = (shift, 0)
        shifted_count = nn.functional.pad(count[:, : num_patches - shift], padding)
        shifted_mean = nn.functional.pad(mean[:, : num_patches - shift], padding)
        shifted_m2 = nn.functional.pad(m2[:, : num_patches - shift], padding)
        count, mean, m2 = _welford_combine(shifted_count, shifted_mean, shifted_m2, count, mean, m2)
        shift *= 2
    return count, mean, m2


def _advancing_block_frames(
    context: torch.Tensor, observed_mask: torch.Tensor, sinh_median: torch.Tensor, minimum_scale: float
) -> tuple[torch.Tensor, torch.Tensor]:
    """
    Per-patch `(loc, scale)` of a decoded block in the advancing frame the model was trained in.

    Horizon patch `j` is normalized with the statistics of the observed context plus the medians of the patches
    `0..j-1` of the block, each median being denormalized in its own frame before it is folded in.

    Args:
        context (`torch.Tensor` of shape `(num_rows, context_length)`):
            Context of the block, `context_length` being a multiple of the patch length.
        observed_mask (`torch.Tensor` of shape `(num_rows, context_length)`):
            Observation mask of the context.
        sinh_median (`torch.Tensor` of shape `(num_rows, num_patches, patch_length)`):
            Median of the block in the frame of the last context patch, `(median - loc) / scale`.
        minimum_scale (`float`):
            Lower bound of the scale.

    Returns:
        `tuple[torch.Tensor, torch.Tensor]`: `(loc, scale)`, float64 tensors of shape `(num_rows, num_patches)`.
    """
    num_rows, num_patches, patch_length = sinh_median.shape
    blank = sinh_median.new_zeros(num_rows, num_patches, patch_length)
    # Per-patch moments of the context, scanned together with the zero-weight horizon patches.
    values = torch.cat([context.unflatten(-1, (-1, patch_length)).to(torch.float64), blank], dim=1)
    weights = torch.cat([observed_mask.unflatten(-1, (-1, patch_length)).to(torch.float64), blank], dim=1)
    count = weights.sum(-1)
    mean = (values * weights).sum(-1) / count.clamp(min=1.0)
    m2 = (weights * (values - mean.unsqueeze(-1)).square()).sum(-1)
    is_empty = count == 0
    mean = torch.where(is_empty, torch.zeros_like(mean), mean)
    m2 = torch.where(is_empty, torch.zeros_like(m2), m2)
    count, mean, m2 = (state[:, -num_patches - 1] for state in _cumulative_welford(count, mean, m2))

    # Medians are clamped relative to the context mean, so that a large level survives the clamp.
    offset = mean
    clip = torch.finfo(torch.float32).max ** 0.5 / 1e3
    locs, scales = [], []
    for patch_idx in range(num_patches):
        variance = (m2 / (count - 1.0).clamp(min=1.0)).clamp(min=0.0)
        scale = variance.sqrt().clamp(min=minimum_scale)
        locs.append(mean)
        scales.append(scale)
        folded = (sinh_median[:, patch_idx] * scale[:, None] + mean[:, None] - offset[:, None]).clamp(-clip, clip)
        folded = folded + offset[:, None]
        block_mean = folded.mean(-1)
        block_m2 = (folded - block_mean[:, None]).square().sum(-1)
        count, mean, m2 = _welford_combine(count, mean, m2, torch.full_like(count, patch_length), block_mean, block_m2)
    return torch.stack(locs, dim=1), torch.stack(scales, dim=1)


def _forward_fill(values: torch.Tensor, observed_mask: torch.Tensor) -> torch.Tensor:
    """Forward-fills the unobserved positions along the last axis. Leading unobserved positions become 0."""
    if observed_mask.all():
        return values
    indices = torch.arange(values.shape[-1], device=values.device).expand_as(values)
    indices = torch.where(observed_mask, indices, torch.zeros_like(indices))
    indices = indices.cummax(dim=-1).values
    return torch.nan_to_num(torch.gather(values, dim=-1, index=indices), nan=0.0)


@auto_docstring(
    custom_intro="""
    Timestral model with a quantile head on top, for probabilistic forecasting. Horizons longer than one block are
    decoded block by block.
    """
)
class TimestralModelForPrediction(TimestralPreTrainedModel):
    def __init__(self, config: TimestralConfig):
        super().__init__(config)

        self.model = TimestralModel(config)
        self.output_projection = TimestralResidualBlock(
            input_dims=config.hidden_size,
            hidden_dims=4 * config.hidden_size,
            output_dims=config.patch_length * len(config.quantiles),
            use_bias=False,
        )

        # Initialize weights and apply final processing
        self.post_init()

    def _prepare_covariates(
        self, covariates: torch.Tensor | None, batch_size: int, length: int, name: str, device: torch.device
    ) -> torch.Tensor | None:
        if covariates is None:
            return None
        if not self.config.use_covariates:
            raise ValueError(f"This checkpoint was not trained with covariates, got `{name}`.")
        covariates = torch.as_tensor(covariates, dtype=torch.float32, device=device)
        if covariates.dim() == 2:
            covariates = covariates[:, None]
        if covariates.dim() != 3 or covariates.shape[0] != batch_size or covariates.shape[-1] != length:
            raise ValueError(
                f"`{name}` must be of shape ({batch_size}, num_covariates, {length}), got {tuple(covariates.shape)}."
            )
        return covariates if covariates.shape[1] > 0 else None

    def _assemble_variates(
        self,
        values: torch.Tensor,
        observed_mask: torch.Tensor,
        prediction_length: int,
        past_covariates: torch.Tensor | None,
        known_covariates: torch.Tensor | None,
    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor | None, torch.Tensor | None, torch.Tensor | None]:
        """
        Stacks the targets and the covariates along the variate axis, keeps the most recent
        `config.context_length` steps and left-pads to a multiple of the patch length.

        Returns `(context, observed_mask, variate_roles, future_known_values, future_known_observed_mask)`.
        """
        patch_length = self.config.patch_length
        batch_size, num_targets, _ = values.shape
        horizon_length = math.ceil(prediction_length / patch_length) * patch_length

        contexts = [_forward_fill(values, observed_mask)]
        masks = [observed_mask]
        roles = [TIMESTRAL_ROLE_TARGET] * num_targets
        num_past = num_known = 0
        if past_covariates is not None:
            num_past = past_covariates.shape[1]
            masks.append(~torch.isnan(past_covariates))
            contexts.append(torch.nan_to_num(past_covariates, nan=0.0))
            roles += [TIMESTRAL_ROLE_PAST_COVARIATE] * num_past
        if known_covariates is not None:
            num_known = known_covariates.shape[1]
            known_context = known_covariates[..., :-prediction_length]
            known_future = known_covariates[..., -prediction_length:]
            masks.append(~torch.isnan(known_context))
            contexts.append(torch.nan_to_num(known_context, nan=0.0))
            roles += [TIMESTRAL_ROLE_KNOWN_COVARIATE] * num_known

        context = torch.cat(contexts, dim=1)
        mask = torch.cat(masks, dim=1)
        if context.shape[-1] > self.config.context_length:
            context = context[..., -self.config.context_length :]
            mask = mask[..., -self.config.context_length :]
        if context.shape[-1] % patch_length != 0:
            # Left padding is 0 and unobserved.
            padding = patch_length - context.shape[-1] % patch_length
            context = nn.functional.pad(context, (padding, 0), value=0.0)
            mask = nn.functional.pad(mask, (padding, 0), value=False)
        if num_past == 0 and num_known == 0:
            return context, mask, None, None, None

        variate_roles = torch.tensor(roles, dtype=torch.long, device=values.device)
        future_known_values = future_known_observed_mask = None
        if num_known > 0:
            num_variates = context.shape[1]
            first_known = num_targets + num_past
            future_known_values = context.new_zeros(batch_size, num_variates, horizon_length)
            future_known_observed_mask = torch.zeros_like(future_known_values, dtype=torch.bool)
            future_known_values[:, first_known:, :prediction_length] = torch.nan_to_num(known_future, nan=0.0)
            future_known_observed_mask[:, first_known:, :prediction_length] = ~torch.isnan(known_future)
        return context, mask, variate_roles, future_known_values, future_known_observed_mask

    def _project(self, outputs: TimestralOutput) -> torch.Tensor:
        """Forecast tokens to quantiles of shape `(batch_size, num_variates, block_length, num_quantiles)`."""
        config = self.config
        raw = self.output_projection(outputs.last_hidden_state)
        raw = raw.unflatten(-1, (config.patch_length, len(config.quantiles)))
        raw = raw.to(torch.promote_types(raw.dtype, torch.float32))
        quantiles = _monotone_quantiles(raw, config.quantiles, config.quantile_width_factor).flatten(2, 3)
        loc = outputs.loc[..., None, None].to(quantiles.device)
        scale = outputs.scale[..., None, None].to(quantiles.device)
        return _unscale_quantiles(quantiles, loc, scale, config.use_asinh)

    def _refine_block(
        self,
        quantiles: torch.Tensor,
        context: torch.Tensor,
        observed_mask: torch.Tensor,
        target_variates: torch.Tensor | None,
    ) -> torch.Tensor:
        """
        Moves a decoded block from the frame of the last context patch to the advancing frame it was trained in.

        The first patch of the block keeps the frame of the last context patch. Each later patch is denormalized
        again with [`_advancing_block_frames`]. Covariates keep their quantiles.
        """
        patch_length = self.config.patch_length
        num_patches = quantiles.shape[2] // patch_length
        if num_patches <= 1:
            return quantiles
        flat_quantiles = quantiles.flatten(0, 1)
        flat_context = context.flatten(0, 1)
        flat_mask = observed_mask.flatten(0, 1)
        with torch.no_grad():
            loc, scale = _causal_patch_statistics(flat_context, flat_mask, patch_length, self.config.minimum_scale)
            anchor_loc, anchor_scale = loc[:, -1], scale[:, -1]
            median = flat_quantiles[..., self.config.median_index].unflatten(-1, (num_patches, patch_length))
            sinh_median = (median.to(torch.float64) - anchor_loc[:, None, None]) / anchor_scale[:, None, None]
            patch_loc, patch_scale = _advancing_block_frames(
                flat_context, flat_mask, sinh_median, self.config.minimum_scale
            )
            is_first = torch.zeros(patch_loc.shape, dtype=torch.bool, device=patch_loc.device)
            is_first[:, 0] = True
            patch_loc = torch.where(is_first, anchor_loc[:, None], patch_loc.to(quantiles.dtype))
            patch_scale = torch.where(is_first, anchor_scale[:, None], patch_scale.to(quantiles.dtype))
            patch_loc = patch_loc.repeat_interleave(patch_length, dim=-1)
            patch_scale = patch_scale.repeat_interleave(patch_length, dim=-1)
        normalized = (flat_quantiles - anchor_loc[:, None, None]) / anchor_scale[:, None, None]
        refined = _clamp_nonfinite(normalized * patch_scale[..., None] + patch_loc[..., None]).view_as(quantiles)
        if target_variates is not None:
            refined = torch.where(target_variates[None, :, None, None], refined, quantiles)
        return refined

    def _cap_quantiles(
        self, quantiles: torch.Tensor, values: torch.Tensor, observed_mask: torch.Tensor
    ) -> torch.Tensor:
        """Clamps the quantiles to `[min - k * scale, max + k * scale]` of the observed context."""
        config = self.config
        unobserved = ~observed_mask
        context_max = torch.nan_to_num(
            values.masked_fill(unobserved, float("-inf")).amax(-1, keepdim=True), neginf=0.0
        )
        context_min = torch.nan_to_num(values.masked_fill(unobserved, float("inf")).amin(-1, keepdim=True), posinf=0.0)
        _, scale = _causal_patch_statistics(values, observed_mask, config.patch_length, config.minimum_scale)
        margin = scale[..., -1:] * config.quantile_cap_factor
        return quantiles.clamp((context_min - margin).unsqueeze(-1), (context_max + margin).unsqueeze(-1))

    def _forecast(
        self,
        values: torch.Tensor,
        observed_mask: torch.Tensor,
        prediction_length: int,
        past_covariates: torch.Tensor | None,
        known_covariates: torch.Tensor | None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor, TimestralOutput]:
        """
        One forecast pass, decoded block by block. After each block the context grows by the feedback of the
        block: targets carry their median, known covariates their real future, covariates only known over the
        context a blank. Past `config.context_length` the oldest steps are dropped.

        Returns the quantiles of the targets, `(batch_size, num_targets, prediction_length, num_quantiles)`, and
        the outputs of the model on the first block.
        """
        config = self.config
        patch_length = config.patch_length
        num_targets = values.shape[1]
        context, mask, variate_roles, future_known_values, future_known_observed_mask = self._assemble_variates(
            values, observed_mask, prediction_length, past_covariates, known_covariates
        )
        initial_context, initial_mask = context, mask

        known_variates = past_variates = target_variates = None
        if variate_roles is not None:
            known_variates = variate_roles == TIMESTRAL_ROLE_KNOWN_COVARIATE
            past_variates = variate_roles == TIMESTRAL_ROLE_PAST_COVARIATE
            target_variates = variate_roles == TIMESTRAL_ROLE_TARGET

        blocks = []
        first_outputs = None
        remaining = math.ceil(prediction_length / patch_length)
        offset = 0
        while remaining > 0:
            num_patches = min(config.block_size, remaining)
            block_length = num_patches * patch_length
            block_known_values = block_known_mask = None
            if future_known_values is not None:
                block_known_values = future_known_values[..., offset : offset + block_length]
                block_known_mask = future_known_observed_mask[..., offset : offset + block_length]
            outputs = self.model(
                past_values=context,
                past_observed_mask=mask,
                num_prediction_patches=num_patches,
                variate_roles=variate_roles,
                future_known_values=block_known_values,
                future_known_observed_mask=block_known_mask,
                **kwargs,
            )
            if first_outputs is None:
                first_outputs = outputs
            quantiles = self._project(outputs)
            quantiles = self._refine_block(quantiles, context, mask, target_variates)
            blocks.append(quantiles)
            remaining -= num_patches
            offset += block_length
            if remaining <= 0:
                break

            feedback = quantiles[..., config.median_index].to(context.dtype)
            feedback = torch.where(
                torch.isfinite(feedback) & (feedback.abs() < config.extreme_value_threshold),
                feedback,
                torch.zeros_like(feedback),
            )
            feedback_mask = torch.ones_like(feedback, dtype=torch.bool)
            if variate_roles is not None:
                if block_known_values is not None:
                    is_known = known_variates[None, :, None]
                    feedback = torch.where(is_known, block_known_values, feedback)
                    feedback_mask = torch.where(is_known, block_known_mask, feedback_mask)
                is_past = past_variates[None, :, None]
                feedback = torch.where(is_past, torch.zeros_like(feedback), feedback)
                feedback_mask = feedback_mask & ~is_past
            context = torch.cat([context, feedback], dim=-1)
            mask = torch.cat([mask, feedback_mask], dim=-1)
            if context.shape[-1] > config.context_length:
                keep = max(patch_length, (config.context_length // patch_length) * patch_length)
                context = context[..., -keep:]
                mask = mask[..., -keep:]

        quantiles = torch.cat(blocks, dim=-2)[:, :num_targets, :prediction_length]
        if config.quantile_cap_factor > 0:
            quantiles = self._cap_quantiles(quantiles, initial_context[:, :num_targets], initial_mask[:, :num_targets])
        if torch.isnan(quantiles).any():
            raise ValueError(
                f"The forecast holds {int(torch.isnan(quantiles).sum())} NaN values, the input is degenerate."
            )
        return quantiles, first_outputs

    @can_return_tuple
    @auto_docstring
    def forward(
        self,
        past_values: torch.Tensor,
        past_observed_mask: torch.Tensor | None = None,
        prediction_length: int | None = None,
        past_covariates: torch.Tensor | None = None,
        known_covariates: torch.Tensor | None = None,
        symmetric_averaging: bool | None = None,
        clip_nonnegative: bool | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> TimestralOutputForPrediction:
        r"""
        past_values (`torch.Tensor` of shape `(batch_size, num_targets, sequence_length)`):
            Context of the series to forecast. `(batch_size, sequence_length)` is read as one target per series
            and `(sequence_length,)` as a single series. NaN marks a missing value. The targets of a series are
            forecast jointly.
        past_observed_mask (`torch.BoolTensor` of shape `(batch_size, num_targets, sequence_length)`, *optional*):
            `False` marks additional missing values of `past_values`.
        prediction_length (`int`, *optional*):
            Number of time steps to forecast. Defaults to one block, `config.block_size * config.patch_length`.
        past_covariates (`torch.Tensor` of shape `(batch_size, num_past_covariates, sequence_length)`, *optional*):
            Covariates known over the context only. NaN marks a missing value.
        known_covariates (`torch.Tensor` of shape `(batch_size, num_known_covariates, sequence_length + prediction_length)`, *optional*):
            Covariates known over the context and the horizon. NaN marks a missing value.
        symmetric_averaging (`bool`, *optional*):
            Whether to average the forecast with the reflected forecast of the negated inputs (covariates
            included). Defaults to `config.symmetric_averaging`.
        clip_nonnegative (`bool`, *optional*):
            Whether to clamp at 0 the forecasts of the series whose observed context is non-negative. Defaults to
            `config.clip_nonnegative`.

        Example:

        ```python
        >>> import torch
        >>> from transformers import TimestralModelForPrediction

        >>> model = TimestralModelForPrediction.from_pretrained("mistralai/Timestral-209M")

        >>> past_values = torch.sin(torch.linspace(0, 60, 512))[None, None, :]
        >>> with torch.no_grad():
        ...     outputs = model(past_values=past_values, prediction_length=64)
        >>> median_forecast = outputs.mean_predictions
        >>> quantile_forecast = outputs.full_predictions
        ```
        """
        config = self.config
        if prediction_length is None:
            prediction_length = config.block_size * config.patch_length
        if prediction_length < 1:
            raise ValueError(f"`prediction_length` must be at least 1, got {prediction_length}.")
        if symmetric_averaging is None:
            symmetric_averaging = config.symmetric_averaging
        if clip_nonnegative is None:
            clip_nonnegative = config.clip_nonnegative

        past_values = past_values.to(torch.float32)
        if past_values.dim() == 1:
            past_values = past_values[None, None]
        elif past_values.dim() == 2:
            past_values = past_values[:, None]
        if past_values.dim() != 3:
            raise ValueError(
                "`past_values` must be of shape (sequence_length,), (batch_size, sequence_length) or "
                f"(batch_size, num_targets, sequence_length), got {tuple(past_values.shape)}."
            )
        observed_mask = torch.isfinite(past_values)
        if past_observed_mask is not None:
            observed_mask = observed_mask & past_observed_mask.to(past_values.device).bool().reshape(past_values.shape)
        values = torch.where(observed_mask, past_values, torch.zeros_like(past_values))

        batch_size, _, sequence_length = values.shape
        past_covariates = self._prepare_covariates(
            past_covariates, batch_size, sequence_length, "past_covariates", values.device
        )
        known_covariates = self._prepare_covariates(
            known_covariates, batch_size, sequence_length + prediction_length, "known_covariates", values.device
        )
        if known_covariates is not None and not config.supports_known_covariates:
            raise ValueError("This checkpoint cannot condition on covariates known over the horizon.")

        quantiles, outputs = self._forecast(
            values, observed_mask, prediction_length, past_covariates, known_covariates, **kwargs
        )
        if symmetric_averaging:
            levels = config.quantiles
            if any(abs(low + high - 1.0) > 1e-9 for low, high in zip(levels, reversed(levels))):
                raise ValueError(f"Symmetric averaging needs quantile levels symmetric about 0.5, got {levels}.")
            # The mirrored pass forecasts the negated series, with every covariate negated too.
            mirrored, _ = self._forecast(
                -values,
                observed_mask,
                prediction_length,
                -past_covariates if past_covariates is not None else None,
                -known_covariates if known_covariates is not None else None,
                **kwargs,
            )
            quantiles = 0.5 * (quantiles + (-mirrored).flip(-1))
        if clip_nonnegative:
            observed_mask = observed_mask.to(quantiles.device)
            values = values.to(quantiles.device)
            is_nonnegative = observed_mask.any(dim=-1) & ((values >= 0) | ~observed_mask).all(dim=-1)
            quantiles = torch.where(is_nonnegative[..., None, None], quantiles.clamp_min(0), quantiles)

        return TimestralOutputForPrediction(
            last_hidden_state=outputs.last_hidden_state,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
            mean_predictions=quantiles[..., config.median_index],
            full_predictions=quantiles,
        )


__all__ = ["TimestralModel", "TimestralModelForPrediction", "TimestralPreTrainedModel"]
